		r = feed("Your TzKal-Zuk kill count is: <col=ff0000>3</col>.",
			"Duration: <col=ff0000>172:18</col>. Personal best: 134:52");
		assertPb(r, "TzKal-Zuk", 134 * 60 + 52, null, 3, false);
